/* ---------- 3. 小工具 ---------- */

window.WORKS_BY_SLUG = {};
(window.WORKS || []).forEach(function (w) { window.WORKS_BY_SLUG[w.slug] = w; });

window.PROJECTS_BY_ID = window.PROJECTS;

/* 站点作品图片地址：列表用 thumb，详情用 work；视频用 poster 封面 */
window.siteImg = function (item, size) {
  if (!item) return '';
  if (item.kind === 'video') return 'https://wzh.homes/video/' + item.slug + '.jpg';
  return 'https://wzh.homes/assets/' + (size === 'full' ? 'work' : 'thumb') + '/' + item.slug + '.webp';
};

window.esc = function (s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
};

/* 图片加载失败时换成内联占位图（data URI，file:// 与离线均可用） */
window.bindImgFallback = function (root) {
  var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="360" height="270">' +
    '<rect width="360" height="270" fill="#efece5"/>' +
    '<text x="180" y="132" font-family="sans-serif" font-size="13" fill="#6d6a63" text-anchor="middle">图片未加载</text>' +
    '<text x="180" y="152" font-family="sans-serif" font-size="11" fill="#8a8781" text-anchor="middle">需联网 · wzh.homes</text>' +
    '</svg>';
  var placeholder = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  var imgs = (root || document).querySelectorAll('img');

  function apply(img) {
    if (img.getAttribute('data-fallback') === '1') return;
    img.setAttribute('data-fallback', '1');
    img.classList.add('img-miss-cell');
    img.src = placeholder;
  }

  Array.prototype.forEach.call(imgs, function (img) {
    /* 脚本执行前就已经失败的图（complete 但无宽度）立即替换 */
    if (img.complete && img.naturalWidth === 0 && img.getAttribute('src')) { apply(img); return; }
    img.addEventListener('error', function () { apply(img); }, { once: true });
  });
};

